package com.medilink.store.entity;
import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import java.sql.Types; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="StoreInventories", uniqueConstraints=@UniqueConstraint(columnNames={"StoreId","MedicineId"})) public class StoreInventory { @Id @JdbcTypeCode(Types.VARCHAR) @Column(name="Id", columnDefinition="char(36)") private UUID id=UUID.randomUUID(); @JdbcTypeCode(Types.VARCHAR) @Column(name="StoreId", columnDefinition="char(36)") private UUID storeId; @JdbcTypeCode(Types.VARCHAR) @Column(name="MedicineId", columnDefinition="char(36)") private UUID medicineId; @Column(name="CreatedAt") private LocalDateTime createdAt=LocalDateTime.now(); public StoreInventory(){} public StoreInventory(UUID storeId,UUID medicineId){this.storeId=storeId;this.medicineId=medicineId;} public UUID getMedicineId(){return medicineId;} }
